// 報名資訊轉發：收到報名事件後，用小龍蝦的LINE官方帳號推播給指定收件人清單
// 收件人清單存在環境變數 NOTIFY_RECIPIENTS（逗號分隔的LINE user id），不寫死在程式碼裡

exports.handler = async (event) => {
  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, body: 'Method Not Allowed' };
  }

  let payload;
  try {
    payload = JSON.parse(event.body || '{}');
  } catch (e) {
    return { statusCode: 400, body: JSON.stringify({ ok: false, error: 'invalid json' }) };
  }

  const { session, name, phone, company, email } = payload;
  if (!session || !name) {
    return { statusCode: 400, body: JSON.stringify({ ok: false, error: 'missing session or name' }) };
  }

  const token = process.env.LINE_CHANNEL_ACCESS_TOKEN;
  const recipients = (process.env.NOTIFY_RECIPIENTS || '').split(',').map(s => s.trim()).filter(Boolean);

  if (!token || recipients.length === 0) {
    return { statusCode: 500, body: JSON.stringify({ ok: false, error: 'not configured' }) };
  }

  const lines = [
    '📋 新報名通知',
    `場次：${session}`,
    `姓名：${name}`,
    phone ? `電話：${phone}` : null,
    company ? `單位：${company}` : null,
    email ? `Email：${email}` : null,
  ].filter(Boolean);
  const text = lines.join('\n');

  const results = await Promise.all(recipients.map(async (to) => {
    try {
      const res = await fetch('https://api.line.me/v2/bot/message/push', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({ to, messages: [{ type: 'text', text }] }),
      });
      return { to, status: res.status };
    } catch (e) {
      return { to, error: String(e) };
    }
  }));

  return { statusCode: 200, body: JSON.stringify({ ok: true, results }) };
};
JSEOF
